<script setup lang="ts">
import { ui } from "../ui"
import DateTime from '../components/DateTime.vue'
import { useRoute,useRouter } from 'vue-router'
import { ref } from 'vue'
import { ArrowPathIcon } from '@heroicons/vue/24/outline'
import PageHeading from '../components/PageHeading.vue'
import { useInvestigation,queryString } from '../composables/investigation'
import type { DeliveryHistoryResult } from '../types'
const route=useRoute(),router=useRouter(),{data,loading,error,reload}=useInvestigation<DeliveryHistoryResult>(()=>'/deliveries?'+queryString(route.query)),environment=ref(String(route.query.environment??'')),issue=ref(String(route.query.issue??'')),rule=ref(String(route.query.rule??''))
function set(key:string,value:string){router.replace({query:{...route.query,page:undefined,[key]:value||undefined}})}
function apply(){router.replace({query:{...route.query,environment:environment.value||undefined,issue:issue.value||undefined,rule:rule.value||undefined,page:undefined}})}
</script>
<template><PageHeading :class="ui('$all', '$PageHeading')" title="Delivery history" subtitle="Durable notification intent, attempts and recovery."><RouterLink to="/alerts" :class="ui('$all', '$a', 'button')">Alert rules</RouterLink><button :class="ui('$all', '$button', 'button icon-button')" aria-label="Refresh deliveries" :disabled="loading" @click="reload"><ArrowPathIcon :class="ui('$all', '$svg')"/></button></PageHeading><div :class="ui('$all', '$div', 'delivery-filters')"><label :class="ui('$all', '$label')">Status<select :class="ui('$all', '$select')" :value="route.query.status??''" @change="set('status',($event.target as HTMLSelectElement).value)"><option :class="ui('$all', '$option')" value="">All statuses</option><option :class="ui('$all', '$option')" v-for="s in ['pending','processing','retrying','sent','cancelled','failed','needs_review']" :key="s">{{s}}</option></select></label><label :class="ui('$all', '$label')">Type<select :class="ui('$all', '$select')" :value="route.query.test??''" @change="set('test',($event.target as HTMLSelectElement).value)"><option :class="ui('$all', '$option')" value="">All deliveries</option><option :class="ui('$all', '$option')" value="1">Tests and report previews</option><option :class="ui('$all', '$option')" value="0">Automatic notifications</option></select></label><label :class="ui('$all', '$label')">Channel<select :class="ui('$all', '$select')" aria-label="Delivery channel"><option :class="ui('$all', '$option')">Email</option></select></label><details :class="ui('$all', '$details')"><summary :class="ui('$all', '$summary')">More filters</summary><form :class="ui('$all', '$form')" @submit.prevent="apply"><label :class="ui('$all', '$label', 'field')">Environment<input :class="ui('$all', '$input')" v-model="environment"></label><label :class="ui('$all', '$label', 'field')">Error UUID<input :class="ui('$all', '$input')" v-model="issue"></label><label :class="ui('$all', '$label', 'field')">Rule UUID<input :class="ui('$all', '$input')" v-model="rule"></label><label :class="ui('$all', '$label', 'field')">Created after (UTC)<input :class="ui('$all', '$input')" type="date" :value="route.query.after" @change="set('after',($event.target as HTMLInputElement).value)"></label><label :class="ui('$all', '$label', 'field')">Created before (UTC)<input :class="ui('$all', '$input')" type="date" :value="route.query.before" @change="set('before',($event.target as HTMLInputElement).value)"></label><button :class="ui('$all', '$button', 'button')">Apply delivery filters</button></form></details></div><div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert">{{error}}<button :class="ui('$all', '$button', 'button')" @click="reload">Try again</button><RouterLink to="/alerts/history" :class="ui('$all', '$a', 'text-link')">Clear filters</RouterLink></div><p :class="ui('$all', '$p')" v-if="loading" role="status">Loading delivery history…</p><template v-if="data"><p :class="ui('$all', '$p', 'notice neutral')">{{data.acceptance_note}}</p><div :class="ui('$all', '$div', 'table-scroll delivery-table')" tabindex="0" role="region" aria-label="Delivery history, scroll for more columns"><table :class="ui('$all', '$table')"><caption :class="ui('$all', '$caption', 'sr-only')">Notification delivery history</caption><thead :class="ui('$all', '$thead')"><tr :class="ui('$all', '$tr')"><th scope="col" :class="ui('$all', '$th')">Event</th><th scope="col" :class="ui('$all', '$th')">Recipient</th><th scope="col" :class="ui('$all', '$th')">Status</th><th scope="col" :class="ui('$all', '$th', 'numeric')">Attempts</th><th scope="col" :class="ui('$all', '$th', 'table-time')">Next eligible / completed</th></tr></thead><tbody :class="ui('$all', '$tbody')"><tr :class="ui('$all', '$tr')" v-for="d in data.items" :key="d.id"><td :class="ui('$all', '$td')"><RouterLink :class="ui('$all', '$a')" :to="'/alerts/history/'+d.id">{{d.action==='connection_test'?'Synthetic test':d.event}}</RouterLink><small :class="ui('$all', '$small')">{{d.environment}} · <DateTime :class="ui('$all', '$DateTime')" :value="d.created_at"/></small></td><td :class="ui('$all', '$td')">{{d.destination_name}}<small :class="ui('$all', '$small')">{{d.destination}}</small></td><td :class="ui('$all', '$td')"><span :class="ui('$all', '$span', 'status-badge', ('status-'+d.status))" >{{d.status}}</span><small :class="ui('$all', '$small')">{{d.reason}}</small></td><td :class="ui('$all', '$td', 'numeric')">{{d.attempts}} <small :class="ui('$all', '$small')">cycle {{d.cycle}}</small></td><td :class="ui('$all', '$td', 'table-time')"><DateTime :class="ui('$all', '$DateTime')" :value="d.completed_at??d.eligible_at"/></td></tr><tr :class="ui('$all', '$tr')" v-if="!data.items.length"><td colspan="5" :class="ui('$all', '$td', 'table-empty')">No deliveries match these filters. <RouterLink to="/alerts/history" :class="ui('$all', '$a', 'text-link')">Clear filters</RouterLink></td></tr></tbody></table></div><div :class="ui('$all', '$div', 'pagination')"><span :class="ui('$all', '$span')">{{data.total}} deliveries · page {{data.page}} of {{data.last_page}}</span><button :class="ui('$all', '$button', 'button')" :disabled="data.page<=1" @click="set('page',String(data.page-1))">Previous deliveries</button><button :class="ui('$all', '$button', 'button')" :disabled="data.page>=data.last_page" @click="set('page',String(data.page+1))">Next deliveries</button></div><p :class="ui('$all', '$p', 'data-caption')">Data as of <DateTime :class="ui('$all', '$DateTime')" :value="data.as_of"/></p></template></template>
